const html = $json.html || '';

const text = html
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/\s+/g, ' ')
  .trim();

const rawDate = $json.internalDate || $json.date || '';

let dateSent = '';

if (rawDate) {
  const date = new Date(rawDate);

  dateSent = date.toLocaleString('en-PH', {
    timeZone: 'Asia/Manila',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: true
  });
}

return [
  {
    json: {
      emailBody: text,
      emailId: $json.id || '',
      messageId: $json.messageId || '',
      senderName: $json.from?.value?.[0]?.name || '',
      senderEmail: $json.from?.value?.[0]?.address || '',
      subject: $json.subject || '',
      dateSent
    }
  }
];

const text = $json.text || '';

const summary = text.match(/SUMMARY:\s*(.*)/i)?.[1]?.trim() || 'None';
const action = text.match(/ACTION:\s*(.*)/i)?.[1]?.trim() || 'None';
const date = text.match(/DATE:\s*(.*)/i)?.[1]?.trim() || 'None';

return [
  {
    json: {
      summary,
      action_required: action,
      important_date: date
    }
  }
];
